type Result<T, E> = Ok<T, E> | Error<E>;

interface Ok<T, E> {
  kind: 'ok';
  value: T;
}

interface Error<E> {
  kind: 'error';
  error: E;
}

function unwrapOr<T, E>(result: Result<T, E>, fallback: T | E): T | E {
  if (result.kind === 'ok') {
    return result.value;
  } else {
    return result.error;
  }
}
